import fs from 'node:fs';
import assert from 'node:assert/strict';
import { capturePublicationInputs, verifySystemsPublicationFreshness, inputsPath } from './tools/sysml-publication-stale.mjs';
const previous = JSON.parse(fs.readFileSync(inputsPath));
const current = capturePublicationInputs(process.cwd());
assert.deepEqual({...current, inputs: null}, {...previous, inputs: null});
const source = 'crates/kerml-semantics/src/trusted_publication.rs';
const transport = 'standards/runtime-transports/sysml-v3-rematerialized-2026-09-25.json';
assert.equal(previous.inputs[source], '962820f0ce931f98684574dcbd651a8335b4ac8536c0d9c5d47ebea9750eea47');
assert.equal(current.inputs[source], 'f280efebad2e03cc194c88ff64dd0a046d5c5a5d28e5e06003bfb05df423261a');
assert.equal(current.inputs[transport], '12cc2aeff7aa7e4a1f3de16faf13d63aa158dd88248e9b3179ad4629e1ffeda0');
assert.equal(previous.inputs[transport], undefined);
const reviewed = {...previous, inputs: {...previous.inputs, [source]: current.inputs[source], [transport]: current.inputs[transport]}};
assert.deepEqual({...current.inputs, 'Cargo.lock': previous.inputs['Cargo.lock']}, reviewed.inputs);
reviewed.inputs = Object.fromEntries(Object.entries(reviewed.inputs).sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0));
fs.writeFileSync(inputsPath, JSON.stringify(reviewed, null, 2) + '\n');
const verified = verifySystemsPublicationFreshness(process.cwd());
console.log(JSON.stringify({grants_publication_authority: false, authority_fields_unchanged: true, prior_lock_pin_preserved: true, reviewed_changes: [source, transport], verified}, null, 2));
